class OBQA(ClassificationDatasetAccess):
    name = 'openbookqa'
    dataset = 'openbookqa'
    x_prefix = ''
    y_prefix = 'answer: '
    y_label = 'answer'
    map_labels = False

    def _load_dataset(self):
        ds = load_dataset(self.dataset)
        # Always take first 10 items from each split for our experiment
        train_ds = ds['train'].select(range(min(10, len(ds['train']))))
        # OBQA splits are train, validation (dev), test
        if 'validation' in ds:
            val_ds = ds['validation'].select(range(min(10, len(ds['validation']))))
        elif 'dev' in ds:
            val_ds = ds['dev'].select(range(min(10, len(ds['dev']))))
        else:
            val_ds = None
        # For testing, ensure we return only 10 as well
        if 'test' in ds:
            test_ds = ds['test'].select(range(min(10, len(ds['test']))))
        else:
            test_ds = None
        # Fallback: if no val or test, reuse train
        if val_ds is None:
            val_ds = train_ds
        if test_ds is None:
            test_ds = train_ds
        # Return train/val or train/test per base class expectation
        return train_ds, val_ds

